contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(
        address asset,
        uint256 amount1,
        uint256 unlock1,
        bool burnable1,
        uint256 amount2,
        uint256 unlock2,
        bool burnable2
    ) public {
        // While not configured, any caller is a successful proposal, so this must succeed.
        c.configureFlashGovernance(asset, amount1, unlock1, burnable1);
        (, uint256 storedAmount1, , ) = c.flashGovernanceConfig();

        // A second call must overwrite all fields: last write wins.
        c.configureFlashGovernance(asset, amount2, unlock2, burnable2);
        (address fa, uint256 famt, uint256 funlock, bool fburn) = c.flashGovernanceConfig();

        // With no pending flash decision, withdrawal must revert.
        bool withdrawReverted;
        try c.withdrawGovernanceAsset(address(c), asset) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        assert(
            storedAmount1 == amount1 &&
            fa == asset &&
            famt == amount2 &&
            funlock == unlock2 &&
            fburn == burnable2 &&
            withdrawReverted
        );
    }
}

