    fallback(bytes calldata) external returns (bytes memory) {
        // acts as Configurable(msg.sender).configured() returning true
        return abi.encode(true);
    }

    function run(uint256 v1, uint256 v2) public {
        c.setEnforcement(false);
        bool revertedOff;
        try c.enforceTolerance(v1, v2) { revertedOff = false; } catch { revertedOff = true; }

        c.setEnforcement(true);
        bool revertedEq;
        try c.enforceTolerance(v1, v1) { revertedEq = false; } catch { revertedEq = true; }

        assert(!revertedOff && !revertedEq);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address dao, address asset, uint256 amount, uint256 unlockTime, bool burnable) public {
        require(dao != address(this));

        // Lock governance configuration.
        c.endConfiguration();

        // onlySuccessfulProposal-gated call must now revert for msg.sender (this contract).
        bool revertedConfig;
        try c.configureFlashGovernance(asset, amount, unlockTime, burnable) { revertedConfig = false; } catch { revertedConfig = true; }

        // setDAO must also revert since configured and msg.sender != DAO and DAO != 0.
        bool revertedDAO;
        try c.setDAO(dao) { revertedDAO = false; } catch { revertedDAO = true; }

        assert(revertedConfig && revertedDAO);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address target, address user, address asset, uint256 amount) public {
        require(target != address(0));
        require(user != address(0));
        require(asset != address(0));
        require(amount > 0);

        // On a fresh (unconfigured) C this onlySuccessfulProposal-gated call succeeds.
        bool revertedBurn;
        try c.burnFlashGovernanceAsset(target, user, asset, amount) { revertedBurn = false; } catch { revertedBurn = true; }

        (uint256 cfgAmount, , address cfgAsset, ) = c.pendingFlashDecision(target, user);

        assert(!revertedBurn && cfgAmount == 0 && cfgAsset == address(0));
    }

    receive() external payable {}
}

