contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 v1, uint256 v2) public {
        require(v1 > v2 && v2 > 0, "need v1>v2>0");
        bool revertedOff;
        bool revertedOn;

        c.setEnforcement(false);
        try c.enforceTolerance(v1, v2) { revertedOff = false; } catch { revertedOff = true; }

        c.setEnforcement(true);
        try c.enforceTolerance(v1, v2) { revertedOn = false; } catch { revertedOn = true; }

        assert(!revertedOff && revertedOn);
    }

    fallback() external payable {
        // act as a configured contract: Configurable(this).configured() -> true
        assembly {
            mstore(0, 1)
            return(0, 32)
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address target, address asset) public {
        // Fresh contract: no flash governance decision has been made,
        // so pendingFlashDecision[target][address(this)].amount == 0
        // and asset == address(0) != asset for any nonzero asset.
        require(true, "");

        bool reverted;
        try c.withdrawGovernanceAsset(target, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: with no pending flash decision for the caller,
        // withdrawal of any governance asset from any target must revert;
        // the decision entry must not exist for it to succeed.
        (uint256 amt, , address a, ) = c.pendingFlashDecision(target, address(this));
        assert(reverted && (amt == 0 || a != asset));
    }

    receive() external payable {}
}

