contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint8 tolerance) public payable {
        require(tolerance > 1 && tolerance < 100);
        // configure is allowed because c is not yet 'configured'
        c.configureSecurityParameters(1, 0, tolerance);
        c.setEnforcement(true);
        bool revertedLargeDeviation;
        try c.enforceTolerance(100, 1) { revertedLargeDeviation = false; }
        catch { revertedLargeDeviation = true; }
        bool revertedEqual;
        try c.enforceTolerance(100, 100) { revertedEqual = false; }
        catch { revertedEqual = true; }
        // deviation 99% must be rejected since tolerance < 100;
        // zero deviation must always be accepted.
        assert(revertedLargeDeviation && !revertedEqual);
    }
    fallback(bytes calldata) external returns (bytes memory) {
        // lets c's `Configurable(msg.sender).configured()` call succeed
        return abi.encode(true);
    }
}

