contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 v1, uint256 v2, uint8 tol) public payable {
        require(v1 < 1e30 && v2 < 1e30, "bounds");
        require(uint256(tol) < 100, "tol range");

        // set tolerance (allowed since configuration not yet ended)
        c.configureSecurityParameters(1, 1, tol);

        // read the actual tolerance from the public getter
        (, , , uint8 actualTol) = c.security();

        // enable enforcement for this caller, probe
        c.setEnforcement(true);
        bool revertedOn;
        try c.enforceTolerance(v1, v2) { revertedOn = false; } catch { revertedOn = true; }

        // disable enforcement for this caller, probe again
        c.setEnforcement(false);
        bool revertedOff;
        try c.enforceTolerance(v1, v2) { revertedOff = false; } catch { revertedOff = true; }

        // expected enforcement decision for this pair, mirroring the tolerance rule
        bool expectRevert;
        if (v1 > v2) {
            if (v2 == 0) expectRevert = v1 > 1;
            else expectRevert = ((v1 - v2) * 100) >= uint256(actualTol) * v1;
        } else {
            if (v1 == 0) expectRevert = v2 > 1;
            else expectRevert = ((v2 - v1) * 100) >= uint256(actualTol) * v1;
        }

        assert(revertedOff == false && revertedOn == expectRevert);
    }

    // C casts this contract to Configurable and calls configured() when enforcement is on
    fallback(bytes calldata) external payable returns (bytes memory) {
        return abi.encode(true);
    }

    receive() external payable {}
}

