    function run(address newDao, address postDao) public payable {
        require(newDao != address(0) && postDao != address(0), "nonzero");
        require(newDao != address(this) && postDao != address(this), "not test");

        // fresh c: configured() is false, so setDAO must succeed for anyone
        bool revertedPre;
        try c.setDAO(newDao) { revertedPre = false; } catch { revertedPre = true; }
        address daoAfterPre = c.DAO();

        // end configuration: only a successful proposal (not us) may proceed,
        // so configured becomes true and setDAO is locked to the DAO address
        bool revertedEnd;
        try c.endConfiguration() { revertedEnd = false; } catch { revertedEnd = true; }

        // now configured: setDAO from any caller that is not the DAO must revert
        bool revertedPost;
        try c.setDAO(postDao) { revertedPost = false; } catch { revertedPost = true; }
        address daoAfterPost = c.DAO();

        assert(
            !revertedPre &&
            daoAfterPre == newDao &&
            !revertedEnd &&
            revertedPost &&
            daoAfterPost == newDao
        );
    }

    receive() external payable {}
}

