contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address[] calldata targets, bool[] calldata flags, bool mismatch) external {
        require(targets.length == flags.length);
        require(targets.length > 0);
        // onlySuccessfulProposal passes because configured() is false at deployment
        require(c.configured() == false);

        if (mismatch) {
            bool[] memory long = new bool[](flags.length + 1);
            for (uint256 i = 0; i < flags.length; i++) long[i] = flags[i];
            bool reverted;
            try c.setGoverned(targets, long) { reverted = false; }
            catch { reverted = true; }
            assert(reverted);
            return;
        }

        c.setGoverned(targets, flags);

        for (uint256 i = 0; i < targets.length; i++) {
            assert(c.governed(targets[i]) == flags[i]);
        }
    }
}

