contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function configured() public pure returns (bool) { return true; }

    function run(uint256 v1, uint256 v2) public payable {
        require(v1 > 0 && v2 > 0);
        require(!c.configured());

        // tolerance defaults to 0; set it explicitly (allowed since DAO not configured yet)
        c.configureSecurityParameters(0, 0, 0);

        // enforcement off by default: never reverts
        bool revertedOff;
        try c.enforceTolerance(v1, v2) { revertedOff = false; } catch { revertedOff = true; }

        // turn on enforcement for msg.sender (this contract, configured() == true)
        c.setEnforcement(true);

        bool revertedOn;
        try c.enforceTolerance(v1, v2) { revertedOn = false; } catch { revertedOn = true; }

        assert(!revertedOff && revertedOn);
    }

    receive() external payable {}
}

