        address[] memory addrs = new address[](1);
        addrs[0] = a;
        bool[] memory flagsBad = new bool[](1 + (pad % 2));
        flagsBad[0] = flag;
        bool revertedMismatch;
        try c.setGoverned(addrs, flagsBad) { revertedMismatch = false; } catch { revertedMismatch = true; }

        // equal lengths: succeeds and records the mapping
        bool[] memory flagsOk = new bool[](1);
        flagsOk[0] = flag;
        c.setGoverned(addrs, flagsOk);

        assert(revertedMismatch && c.governed(a) == flag);
    }

    receive() external payable {}
}

contract InvMutTest {
