        // while not configured, anyone (including this non-DAO sender) may set DAO
        bool okBefore;
        try c.setDAO(dao2) { okBefore = true; } catch { okBefore = false; }

        // configuration can be ended by anyone, then DAO is frozen
        c.endConfiguration();

        bool okAfter;
        try c.setDAO(dao2) { okAfter = true; } catch { okAfter = false; }

        assert(okBefore && !okAfter);
    }

    receive() external payable {}
}

